// Checkout conversion module - ensures paid events are generated
const crypto = require('crypto');
const { logAction } = require('./logger');

async function processCheckout(session) {
  // Simulate payment processing
  const paymentId = crypto.randomUUID();
  const amount = session.amount || 0;
  const status = amount > 0 ? 'paid' : 'free';

  // Record paid event
  if (status === 'paid') {
    await logAction('PAID_EVENT', { paymentId, amount, sessionId: session.id });
    // Increment paidEvents counter (shared state via Redis or file)
    const fs = require('fs').promises;
    const counterPath = '/opt/unicorn/data/paidEvents.json';
    let counter = { count: 0 };
    try {
      const data = await fs.readFile(counterPath, 'utf8');
      counter = JSON.parse(data);
    } catch (e) { /* file may not exist */ }
    counter.count += 1;
    await fs.writeFile(counterPath, JSON.stringify(counter));
  }

  return { paymentId, status };
}

module.exports = { processCheckout };
